me-control" type="range" min="0.8" max="1.5" step="0.1" name="heading_scale" value="{{ old('heading_scale',$s['heading_scale']??1) }}"></div><div class="col-md-4"><label class="form-label">Corner radius</label><input class="form-range theme-control" type="range" min="0" max="32" name="radius" value="{{ old('radius',$s['radius']??16) }}"></div></div><button class="btn btn-primary mt-4"><i class="fas fa-floppy-disk me-1"></i>Save theme</button></div></div></div><div class="col-xl-5"><div class="card admin-panel sticky-top" style="top:90px"><div class="card-header">Live preview</div><div id="themePreview" style="min-height:440px;padding:24px"><nav style="height:48px;border-radius:10px;margin-bottom:28px"></nav><p class="small fw-bold">PROFESSIONAL SERVICES</p><h2>Your website, your brand.</h2><p class="preview-copy">Preview colors, typography and spacing before saving.</p><button type="button" class="btn">Explore services</button><div class="mt-4 p-4 preview-card"><strong>Secure platform</strong><p class="mb-0 mt-2">Protected functional layout with customizable appearance.</p></div></div></div></div></div></form>
<script>const form=document.querySelector('form'),preview=document.getElementById('themePreview');function paint(){const v=n=>form.elements[n].value;preview.style.cssText=`min-height:440px;padding:24px;background:${v('background')};color:${v('text')};font-family:${v('body_font')};font-size:${v('base_font_size')}px`;preview.querySelector('nav').style.background=v('surface');preview.querySelector('h2').style.cssText=`color:${v('text')};font-family:${v('heading_font')};font-size:${2.2*v('heading_scale')}rem`;preview.querySelector('.small').style.color=v('accent');preview.querySelector('.preview-copy').style.color=v('muted');preview.querySelector('button').style.cssText=`background:${v('primary')};color:white;border-radius:${v('radius')}px`;preview.querySelector('.preview-card').style.cssText=`background:${v('surface')};border:1px solid ${v('accent')};border-radius:${v('radius')}px`}document.querySelectorAll('.theme-control').forEach(x=>x.addEventListener('input',paint));paint();</script>
